+#ifdef FRAGS_DEBUG_SANITY_CHECK
+static void
+sanity_check_frag_list(const fragment_head *fd_head)
+{
+	const fragment_item *fd_i;
+	guint32 contiguous_len = 0;
+
+	if (!fd_head)
+		return;
+	g_assert(fd_head->prev == NULL);
+	for(fd_i = fd_head; fd_i->next; fd_i = fd_i->next) {
+		if (fd_i->next)
+			g_assert(fd_i->next->prev == fd_i);
+	}
+	g_assert(fd_head->tail == fd_i);
+	for(; fd_i->prev; fd_i = fd_i->prev) {
+		if (fd_i->prev)
+			g_assert(fd_i->prev->next == fd_i);
+	}
+	g_assert(fd_i == fd_head);
+
+	for (fd_i = fd_head->next; fd_i; fd_i = fd_i->next) {
+		guint32 frag_end = fd_i->offset + fd_i->len;
+		if (fd_i->offset <= contiguous_len && contiguous_len < frag_end) {
+			contiguous_len = frag_end;
+		}
+	}
+	g_assert(fd_head->contiguous_len == contiguous_len);
+}
+#else
+static void
+sanity_check_frag_list(__attribute__((unused)) const fragment_head *fd_head)
